  // Scratch memory reused by every call: the output slots and a growing input buffer.
  final Pointer<TgBytes> _bytes = calloc<TgBytes>();
  final Pointer<Uint64> _word = calloc<Uint64>();
  final Pointer<_TgSearchOptions> _searchOptions = calloc<_TgSearchOptions>();
  final Pointer<_TgOpenOptions> _openOptions = calloc<_TgOpenOptions>();
  final Pointer<_TgInstallOptions> _installOptions = calloc<_TgInstallOptions>();
  Pointer<Uint8> _input = nullptr;
  int _inputCap = 0;

  /// Most rows `sample_rows` builds in one call.
  static const int sampleRowsMax = 1000000;

  /// Most places one query returns.
  static const int limitMax = 10000;

  /// Frees the scratch memory; the instance cannot be used afterwards.
  void close() {
    calloc.free(_bytes);
    calloc.free(_word);
    calloc.free(_searchOptions);
    calloc.free(_openOptions);
    calloc.free(_installOptions);
    if (_inputCap > 0) malloc.free(_input);
  }

  /// [text] as UTF-8 in the scratch buffer at byte [at]; returns its length. ASCII (most
  /// names) is copied code unit by code unit; anything else goes through the UTF-8 encoder.
  int _utf8(String text, [int at = 0]) {
    final n = text.length;
    if (at + n * 3 > _inputCap) _grow(at + n * 3);
    final dst = _input.asTypedList(_inputCap);
    for (var i = 0; i < n; i++) {
      final u = text.codeUnitAt(i);
      if (u >= 0x80) return _utf8Slow(text, dst, at);
      dst[at + i] = u;
    }
    return n;
  }

  /// [bytes] in the scratch buffer at byte [at]; returns their length.
  int _copy(Uint8List bytes, [int at = 0]) {
    if (at + bytes.length > _inputCap) _grow(at + bytes.length);
    _input.asTypedList(_inputCap).setAll(at, bytes);
    return bytes.length;
  }

  int _utf8Slow(String text, Uint8List dst, int at) {
    final bytes = utf8.encode(text);
    dst.setRange(at, at + bytes.length, bytes);
    return bytes.length;
  }

  /// A larger scratch buffer, keeping what an earlier argument of the same call wrote.
  void _grow(int need) {
    final (old, oldCap) = (_input, _inputCap);
    _inputCap = need < 256 ? 256 : need * 2;
    _input = malloc<Uint8>(_inputCap);
    if (oldCap > 0) {
      _input.asTypedList(oldCap).setAll(0, old.asTypedList(oldCap));
      malloc.free(old);
    }
  }

  void _check(int status) {
    if (status == 0) return;
    final code = _lastError(_bytes);
    throw TeiGeodataException._of(code, _takeString());
  }

  String _takeString() {
    final b = _bytes.ref;
    final s = b.len == 0 ? '' : utf8.decode(b.ptr.asTypedList(b.len));
    _free(b);
    return s;
  }

  Uint8List _takeBlob() {
    final b = _bytes.ref;
    final out = Uint8List(b.len)..setRange(0, b.len, b.ptr.asTypedList(b.len));
    _free(b);
    return out;
  }

  /// The library version, from its package metadata.
  String version() {
    final status = _version(_bytes);
    _check(status);
    return _takeString();
  }

  /// Does nothing. Measures the bare cost of a call across each boundary.
  void noop() {
    final status = _noop();
    _check(status);
  }

  /// The search fold of a name: NFKD, lower case, optional accents dropped by script, spaces
  /// collapsed, recomposed to NFC. The same fold the forge and the search index use.
  String fold(String text) {
    final textLen = _utf8(text);
    final status = _fold(_input, textLen, _bytes);
    _check(status);
    return _takeString();
  }

  /// Builds `rows` deterministic sample places as a blob with the columns `id` (`u32`), `lat`
  /// and `lon` (`f64`, degrees), `elevation` (`f32`, metres) and `name` (UTF-8). Exercises the
  /// result path of every binding.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` if `rows` exceeds `SAMPLE_ROWS_MAX`.
  Uint8List sampleRows(int rows) {
    final status = _sampleRows(rows, _bytes);
    _check(status);
    return _takeBlob();
  }

  /// Calls `on_step` once per step with the step number, from 1 to `steps`, on the calling
  /// thread, and returns the number of steps run. Exercises callbacks in every binding.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Cancelled` if `on_step` returns `false`.
  int progress(int steps, bool Function(int) onStep) {
    Object? raised;
    StackTrace? trace;
    final callable = NativeCallable<CallbackU32>.isolateLocal(
      (Pointer<Void> _, int a0) {
        try {
          return onStep(a0);
        } catch (e, s) {
          raised = e;
          trace = s;
          return false;
        }
      },
      exceptionalReturn: false,
    );
    final int status;
    try {
      status = _progress(steps, callable.nativeFunction, nullptr, _word.cast());
    } finally {
      callable.close();
    }
    if (raised != null) Error.throwWithStackTrace(raised!, trace!);
    _check(status);
    return _word.cast<Uint32>().value;
  }

  /// Great-circle distance in metres between two points in degrees, by the haversine formula on
  /// the WGS84 mean sphere (error up to about 0.5% against the ellipsoid).
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` if a latitude is outside -90..=90, a longitude outside
  /// -180..=180, or any value is not finite.
  double distanceM(double lat1, double lon1, double lat2, double lon2) {
    final status = _distanceM(lat1, lon1, lat2, lon2, _word.cast());
    _check(status);
    return _word.cast<Double>().value;
  }

