  ///
  /// `ErrorCode::InvalidArgument` if `id` is not a place ID; `ErrorCode::Corrupt` if a
  /// section read is corrupt.
  Uint8List postalCodesOf(String id) => _lib._enginePostalCodesOf(_live, id);

  /// The postal codes of the point: those of the deepest admin unit holding it that an
  /// admin-aligned scheme gives codes to, with its parts (a ward's code; the point is in one
  /// of them). No rows where no unit holding the point has such codes.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for a point off the globe; `ErrorCode::Corrupt` if a
  /// section read is corrupt.
  Uint8List postalAt(double lat, double lon) => _lib._enginePostalAt(_live, lat, lon);

  /// The time-zone area holding the point (one row; its `tz` column is the IANA zone), or no
  /// row where no pack answers.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for a point off the globe; `ErrorCode::Corrupt` if a
  /// section read is corrupt.
  Uint8List tzAt(double lat, double lon) => _lib._engineTzAt(_live, lat, lon);

  /// The UTC offset in force in `zone` (a tzdb name or link, `Asia/Kathmandu`) at
  /// `unix_seconds`, from the first layer whose zone rules hold the zone: one row with
  /// `seconds` east of UTC, `dst` (1 when tzdb counts it as daylight saving time) and
  /// `abbr` (`+0545`, `EDT`); no row where no layer holds the zone.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for an instant outside the years ±9,999;
  /// `ErrorCode::MissingComponent` if the rules that would hold the zone were not
  /// installed; `ErrorCode::Corrupt` if they are corrupt.
  Uint8List tzOffsetAt(String zone, int unixSeconds) => _lib._engineTzOffsetAt(_live, zone, unixSeconds);

  /// The offsets a civil time may have in `zone`: one row with `kind` (`unique`, `gap` for
  /// a time a transition skips, `overlap` for one that happens twice), `before` and `after`
  /// in seconds east of UTC (the offsets before and after the transition: for an overlap
  /// the earlier and the later instant's; for a unique time both the same); no row where no
  /// layer holds the zone.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for a date that is not one of the years ±9,999 or a time
  /// out of range; otherwise as `Engine::tz_offset_at`.
  Uint8List tzLocal(String zone, int year, int month, int day, int hour, int minute, int second) => _lib._engineTzLocal(_live, zone, year, month, day, hour, minute, second);

  /// Every zone name (tzdb names and links) the layers' zone rules hold, in byte order:
  /// one `zone` column.
  ///
  /// # Errors
  ///
  /// `ErrorCode::MissingComponent` if no installed layer has rules and one has rules that
  /// were not installed.
  Uint8List tzZones() => _lib._engineTzZones(_live);

  /// The earliest instant `zone`'s rules cover, in Unix seconds: one `unix` row (its first
  /// transition, before which tzdb knows only local mean time; the year −9,999 for a zone
  /// that never changed); no row where no layer holds the zone.
  ///
  /// # Errors
  ///
  /// As `Engine::tz_offset_at`.
  Uint8List tzRulesStart(String zone) => _lib._engineTzRulesStart(_live, zone);

  /// The tzdb release (`2026f`) of the first layer with zone rules; empty without rules.
  String tzVersion() => _lib._engineTzVersion(_live);

  /// The place whose ISO 3166 code is `code` (`NP`, `NP-P3`, either case), or no row.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` if `code` is not an ISO 3166 code;
  /// `ErrorCode::Corrupt` if a section read is corrupt.
  Uint8List byIso(String code) => _lib._engineByIso(_live, code);
}

/// A store of installed packs in one directory: its signed catalog, its packs and their
/// journal (D-171), shared by every language and the command line (research note
/// store-api). Long work runs as a `Job` on a thread of its own; one store runs its jobs
/// one at a time, and its other calls wait for the job running.
///
/// Packs are named as catalog paths (`np.places.tgd`) or short (`np`, `np.dem`), several
/// comma-separated. Results are blobs:
/// - `catalog`: `path`, `release`, `download`, `disk`, `components`,
///   `licence`, `state` (`available`, `installed` or `update`);
/// - `status`: `path`, `release`, `bytes`, `pinned`, `asked`, `health`
///   (`good`, `length`, `head`, `footer` or `sections`), `components`;
/// - an install or update: `path`, `release`, `fetched`, `reused`, `kept`, `changed`;
/// - a refresh: `timestamp`, `files`, `bytes`; a repair: `path`, `health`, `fetched`;
///   `remove`: `path`, `release`;
/// - `find` and `locate`: one row per place and pack that
///   covers it: `id`, `name`, `lat`, `lon`, `countries`, then the pack's `pack`, `release`,
///   `download`, `disk` and `state`, null for a place no pack in the catalog covers.
///
/// Freed by [close], or when collected if never closed. Use it on the isolate that made it.
final class Store implements Finalizable {
  Store._(this._lib, this._handle) {
    _lib._storeFinalizer.attach(this, _handle, detach: this);
  }


  final TeiGeodata _lib;
  Pointer<Void> _handle;

  // Asynchronous calls still using the handle, and the handle closed while they run: it is
  // freed when the last of them ends.
  int _pending = 0;
  Pointer<Void> _closed = nullptr;

  Pointer<Void> get _live => _handle == nullptr ? throw StateError('Store is closed') : _handle;

  /// Frees the handle now; later calls throw a [StateError]. Closing twice does nothing. An
  /// asynchronous call still running keeps it until it ends.
  void close() {
    if (_handle == nullptr) return;
    _lib._storeFinalizer.detach(this);
    if (_pending > 0) {
      _closed = _handle;
    } else {
      _free(_handle);
    }
    _handle = nullptr;
  }

  void _free(Pointer<Void> handle) =>
      _lib._storeFree.asFunction<void Function(Pointer<Void>)>(isLeaf: true)(handle);

  /// The handle's address for a helper isolate; it stays open until [_unhold].
  int _hold() {
    final address = _live.address;
    _pending++;
    return address;
  }

  void _unhold() {
    if (--_pending == 0 && _closed != nullptr) {
      _free(_closed);
      _closed = nullptr;
    }
  }

  /// Hands the handle over to another isolate: its address, no longer freed here.
  int _take() {
    _lib._storeFinalizer.detach(this);
    final address = _handle.address;
    _handle = nullptr;
    return address;
  }

  /// Sets up a store at `root` and opens it: the metadata mirrors `repo` and asset mirrors
  /// `assets` (comma-separated URLs), and `trusted_root`, the catalog's root metadata, which
  /// becomes its trust anchor once it verifies by itself. A store set up before is set up
  /// again with these.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Refused` if the root does not verify or the store cannot be written.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  static Store create(TeiGeodata lib, String root, String repo, String assets, Uint8List trustedRoot) => lib._storeCreate(root, repo, assets, trustedRoot);

  /// [create] on a helper isolate, so it never blocks this one.
  static Future<Store> createAsync(TeiGeodata lib, String root, String repo, String assets, Uint8List trustedRoot) =>
      _storeCreateOff(lib._path, root, repo, assets, trustedRoot).then((address) => Store._(lib, Pointer.fromAddress(address)));

  /// Opens the store at `root`, finishing or undoing an install a crash cut short.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Refused` if it is not a store or its journal cannot be read.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  static Store open(TeiGeodata lib, String root) => lib._storeOpen(root);

  /// [open] on a helper isolate, so it never blocks this one.
  static Future<Store> openAsync(TeiGeodata lib, String root) =>
      _storeOpenOff(lib._path, root).then((address) => Store._(lib, Pointer.fromAddress(address)));

  /// The packs found damaged when the store was opened, comma-separated; empty when none.
  /// `repair` fetches what they lack.
  String damaged() => _lib._storeDamaged(_live);

  /// The verified catalog as stored, one row per pack, with its state against the store.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Refused` before a refresh, or if the stored catalog no longer verifies.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  Uint8List catalog() => _lib._storeCatalog(_live);

  /// [catalog] on a helper isolate, so it never blocks this one.
  Future<Uint8List> catalogAsync() {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _storeCatalogOff(lib._path, self).whenComplete(() {
      _unhold();
    });
  }

  /// Each installed pack and its health, from a full check of every byte when `deep`.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Refused` if a pack cannot be read.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  Uint8List status(bool deep) => _lib._storeStatus(_live, deep);

  /// [status] on a helper isolate, so it never blocks this one.
  Future<Uint8List> statusAsync(bool deep) {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _storeStatusOff(lib._path, self, deep).whenComplete(() {
      _unhold();
    });
  }

  /// Pins the pack (kept when room is made), or unpins it.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Refused` if it is not installed.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  void pin(String pack, bool on) => _lib._storePin(_live, pack, on);

  /// [pin] on a helper isolate, so it never blocks this one.
  Future<void> pinAsync(String pack, bool on) {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _storePinOff(lib._path, self, pack, on).whenComplete(() {
      _unhold();
    });
  }

  /// Removes the packs and the dependencies nothing else needs; returns what was removed.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Refused` if one is not installed or another pack needs it.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  Uint8List remove(String pack) => _lib._storeRemove(_live, pack);

  /// [remove] on a helper isolate, so it never blocks this one.
  Future<Uint8List> removeAsync(String pack) {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _storeRemoveOff(lib._path, self, pack).whenComplete(() {
      _unhold();
    });
  }

  /// The places named `query` in `engine` (one over a world pack the app ships, the
  /// installed packs, or both), best first, each with the catalog's packs that cover it: what
  /// to install for "Dubai". Runs offline on the stored catalog.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for a limit above `LIMIT_MAX`;
  /// `ErrorCode::Refused` if the stored catalog no longer verifies.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  Uint8List find(Engine engine, String query, int limit) => _lib._storeFind(_live, engine, query, limit);

  /// [find] on a helper isolate, so it never blocks this one.
  Future<Uint8List> findAsync(Engine engine, String query, int limit) {
    // Every handle is checked open before any is held.
    _live;
    engine._live;
    final lib = _lib, self = _hold();
    final engineAt = engine._hold();
    return _storeFindOff(lib._path, self, engineAt, query, limit).whenComplete(() {
      _unhold();
      engine._unhold();
    });
  }

  /// The countries within `radius_m` metres of a point in `engine`, each with the catalog's
  /// packs that cover the point: what to install for where the user stands.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for a point off the globe; `ErrorCode::Refused` if
  /// the stored catalog no longer verifies.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  Uint8List locate(Engine engine, double lat, double lon, int radiusM) => _lib._storeLocate(_live, engine, lat, lon, radiusM);

  /// [locate] on a helper isolate, so it never blocks this one.
  Future<Uint8List> locateAsync(Engine engine, double lat, double lon, int radiusM) {
    // Every handle is checked open before any is held.
    _live;
    engine._live;
    final lib = _lib, self = _hold();
    final engineAt = engine._hold();
    return _storeLocateOff(lib._path, self, engineAt, lat, lon, radiusM).whenComplete(() {
      _unhold();
      engine._unhold();
    });
  }

  /// An engine over the installed packs, each opened with the components and languages
  /// installed.
  ///
  /// # Errors
  ///
  /// `ErrorCode::Io` or `ErrorCode::Corrupt` if a pack cannot be opened.
  ///
  /// # Blocks
  ///
  /// While a job of this store runs, and on the disk: call it off a UI thread, or use the
  /// language's asynchronous form.
  Engine engine() => _lib._storeEngine(_live);

  /// [engine] on a helper isolate, so it never blocks this one.
  Future<Engine> engineAsync() {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _storeEngineOff(lib._path, self).then((address) => Engine._(lib, Pointer.fromAddress(address))).whenComplete(() {
      _unhold();
    });
  }

  /// Refreshes the catalog for the countries (comma-separated ISO codes) and every country
  /// installed. Fails with `ErrorCode::Network` or `ErrorCode::Refused`.
  Job refresh(String countries) => _lib._storeRefresh(_live, countries);

  /// Installs the packs with `options`, dependencies first, refreshing the catalog for their
  /// countries. Cancelled, it leaves the store as it was; the packs installed before the
  /// one cut stay installed.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` for an unknown component or language tag, more than 8
  /// languages, or an outline level above 255; the job's own errors are the job's.
  Job install(String packs, InstallOptions options) => _lib._storeInstall(_live, packs, options);

  /// One pass of an install whose bytes a platform's own download service fetches (D-184),
  /// for downloads that must go on while the app is suspended. The pass reads each asset's
  /// ranges from files under `dir`, checks every byte as from any host, and its result lists
  /// what is still missing, one row per range: `pack`, `urls` (the asset on each mirror, one
  /// per line), `length` (the asset's), `start` and `end` (the range, end exclusive) and
  /// `file`, where to save those bytes. Fetch every listed range (an HTTP `Range` request
  /// for `bytes=start-(end-1)`), then run the pass again; a result with no rows means the
  /// packs are installed and their files under `dir` removed. A first install takes three
  /// passes.
  ///
  /// # Errors
  ///
  /// `ErrorCode::InvalidArgument` as for `Store::install`, or for an empty `dir`; the
  /// job's own errors are the job's.
  Job installPass(String packs, String dir, InstallOptions options) => _lib._storeInstallPass(_live, packs, dir, options);

  /// Updates the packs (every installed one when empty) to the catalog's releases, keeping
  /// the components and languages installed.
  Job update(String packs) => _lib._storeUpdate(_live, packs);

  /// Checks the pack in full and, unless it is whole, fetches what it lacks.
  Job repair(String pack) => _lib._storeRepair(_live, pack);
}

/// A store's long work on a thread of its own (D-274): its progress in bytes, a wait for the
/// next change, a cancel, and its result.
///
/// # Job
///
/// Each language builds its own idioms on these methods: a stream of progress, and the
/// awaited result cancelling the job when the caller's task is cancelled.
///
/// Freed by [close], or when collected if never closed. Use it on the isolate that made it.
final class Job implements Finalizable {
  Job._(this._lib, this._handle) {
    _lib._jobFinalizer.attach(this, _handle, detach: this);
  }


  final TeiGeodata _lib;
  Pointer<Void> _handle;

  // Asynchronous calls still using the handle, and the handle closed while they run: it is
  // freed when the last of them ends.
  int _pending = 0;
  Pointer<Void> _closed = nullptr;

  Pointer<Void> get _live => _handle == nullptr ? throw StateError('Job is closed') : _handle;

  /// Frees the handle now; later calls throw a [StateError]. Closing twice does nothing. An
  /// asynchronous call still running keeps it until it ends.
  void close() {
    if (_handle == nullptr) return;
    _lib._jobFinalizer.detach(this);
    if (_pending > 0) {
      _closed = _handle;
    } else {
      _free(_handle);
    }
    _handle = nullptr;
  }

  void _free(Pointer<Void> handle) =>
      _lib._jobFree.asFunction<void Function(Pointer<Void>)>(isLeaf: true)(handle);

  /// The handle's address for a helper isolate; it stays open until [_unhold].
  int _hold() {
    final address = _live.address;
    _pending++;
    return address;
  }

  void _unhold() {
    if (--_pending == 0 && _closed != nullptr) {
      _free(_closed);
      _closed = nullptr;
    }
  }

  /// Waits until the progress moves past `seq` (from `seq`), the job ends, or
  /// `timeout_ms` passes; returns the sequence then. Polling with the last one returned
  /// sees every change.
  ///
  /// # Blocks
  ///
  /// Until the job moves or ends: call it off a UI thread, or use the language's
  /// asynchronous form.
  int waitProgress(int seq, int timeoutMs) => _lib._jobWaitProgress(_live, seq, timeoutMs);

  /// [waitProgress] on a helper isolate, so it never blocks this one.
  Future<int> waitProgressAsync(int seq, int timeoutMs) {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _jobWaitProgressOff(lib._path, self, seq, timeoutMs).whenComplete(() {
      _unhold();
    });
  }

  /// The progress's sequence number: it moves on with every change.
  int seq() => _lib._jobSeq(_live);

  /// Bytes received so far.
  int doneBytes() => _lib._jobDoneBytes(_live);

  /// Bytes expected, from the catalog's sizes: never below the bytes received, and equal
  /// to them once the job ends.
  int totalBytes() => _lib._jobTotalBytes(_live);

  /// Whether the job has ended (done, failed or cancelled); its result is then ready.
  bool isEnded() => _lib._jobIsEnded(_live);

  /// Asks the job to stop at its next request or chunk; it then fails with
  /// `ErrorCode::Cancelled` and leaves the store as it was.
  void cancel() => _lib._jobCancel(_live);

  /// The job's result, waiting for it to end.
  ///
  /// # Errors
  ///
  /// The job's: `ErrorCode::Network`, `ErrorCode::Refused`, `ErrorCode::Cancelled`,
  /// or `ErrorCode::Io` and `ErrorCode::Corrupt` for an engine's packs.
  ///
  /// # Blocks
  ///
  /// Until the job moves or ends: call it off a UI thread, or use the language's
  /// asynchronous form.
  Uint8List result() => _lib._jobResult(_live);

  /// [result] on a helper isolate, so it never blocks this one.
  Future<Uint8List> resultAsync() {
    // Every handle is checked open before any is held.
    _live;
    final lib = _lib, self = _hold();
    return _jobResultOff(lib._path, self).whenComplete(() {
      _unhold();
    });
  }

  /// The job's progress in bytes: now, then at each change, ending when the job ends (the
  /// last at its total). Cancelling the subscription stops the waiting, not the job; for that,
  /// [cancel].
  Stream<({int done, int total})> progress() async* {
    var seq = this.seq();
    var last = (done: doneBytes(), total: totalBytes());
    yield last;
    while (!isEnded()) {
      final next = await waitProgressAsync(seq, 250);
      if (next != seq) {
        seq = next;
        last = (done: doneBytes(), total: totalBytes());
        yield last;
      }
    }
    final end = (done: doneBytes(), total: totalBytes());
    if (end != last) yield end;
  }
}

/// The body of `Store.createAsync`, run on a helper isolate. A top-level
/// function, so the closure sent there holds only its arguments.
Future<int> _storeCreateOff(String path, String root, String repo, String assets, Uint8List trustedRoot) =>
    Isolate.run(() {
      final lib = TeiGeodata.open(path);
      try {
        return lib._storeCreate(root, repo, assets, trustedRoot)._take();
      } finally {
        lib.close();
      }
    });

